// Study notes library: reads the file index (manifest.json, generated by GitHub Pages)
// and renders courses, weeks and documents. Routes live in the URL hash:
//   #/                                 all courses
//   #/<course>                         weeks of one course
//   #/<course>/week-<n>[/overview|/notes]  one week's documents
(() => {
  "use strict";

  // CaseNotes3.pdf, Overview3.html, "Case Notes 3.pdf", overview_3.htm ...
  const FILE_PATTERN = /^(case[\s_-]*notes?|overview)[\s_-]*(\d+)\.([a-z0-9]+)$/i;
  const PDFJS = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/";
  const DESKTOP = window.matchMedia("(min-width: 960px)");

  const layout = document.getElementById("layout");
  const view = document.getElementById("view");
  const sidebar = document.getElementById("sidebar");
  const courseTree = document.getElementById("course-tree");
  const courseNav = document.getElementById("course-nav");

  let courses = [];
  let lastRoute = null;

  // ---------- Data ----------

  const slugify = (text) =>
    text.toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g, "")
      .replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "course";

  // Manifest paths look like "/course_notes/<course>/<file>"; the library lives one level down.
  const fileUrl = (path) => ".." + path.split("/").map(encodeURIComponent).join("/");

  function buildLibrary(paths) {
    const byName = new Map();
    for (const path of paths) {
      const parts = path.split("/").filter(Boolean);
      if (parts.length < 3) continue;
      const name = parts[1];
      const fileName = parts[parts.length - 1];
      if (!byName.has(name)) byName.set(name, { name, slug: slugify(name), weeks: new Map(), other: [] });
      const course = byName.get(name);

      const ext = fileName.split(".").pop().toLowerCase();
      const file = { name: fileName, url: fileUrl(path), type: ext === "pdf" ? "pdf" : /^html?$/.test(ext) ? "html" : "other" };
      const match = FILE_PATTERN.exec(fileName);
      if (!match || file.type === "other") {
        course.other.push(file);
        continue;
      }
      const number = parseInt(match[2], 10);
      if (!course.weeks.has(number)) course.weeks.set(number, { number });
      course.weeks.get(number)[/^overview/i.test(match[1]) ? "overview" : "notes"] = file;
    }

    const byText = (a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" });
    return [...byName.values()]
      .sort((a, b) => byText(a.name, b.name))
      .map((course) => ({
        ...course,
        weeks: [...course.weeks.values()].sort((a, b) => a.number - b.number),
        other: course.other.sort((a, b) => byText(a.name, b.name)),
      }));
  }

  // ---------- Routing ----------

  function parseRoute() {
    const parts = location.hash.replace(/^#\/?/, "").split("/").filter(Boolean).map(decodeURIComponent);
    const week = parts[1] && /^week-(\d+)$/.exec(parts[1]);
    return { course: parts[0] || null, week: week ? parseInt(week[1], 10) : parts[1] ? NaN : null, tab: parts[2] || null };
  }

  function href(course, week, tab) {
    let hash = "#/";
    if (course) hash += course.slug;
    if (week) hash += "/week-" + week.number;
    if (week && tab) hash += "/" + tab;
    return hash;
  }

  function render() {
    const route = parseRoute();
    const sameWeek = lastRoute && route.week != null && lastRoute.course === route.course && lastRoute.week === route.week;
    const isFirstRender = lastRoute === null;
    lastRoute = route;

    const course = courses.find((c) => c.slug === route.course);
    const week = course && course.weeks.find((w) => w.number === route.week);
    if (!route.course) renderHome();
    else if (!course) renderMissing("There is no course at this address.");
    else if (route.week == null) renderCourse(course);
    else if (!week) renderMissing("This week isn't in " + course.name + ".", course);
    else renderWeek(course, week, route.tab);

    if (!DESKTOP.matches) courseTree.open = false;
    if (isFirstRender) return;
    if (sameWeek) {
      const tab = view.querySelector(".doc-tabs [aria-current]");
      if (tab) tab.focus({ preventScroll: true });
    } else {
      window.scrollTo(0, 0);
      view.querySelector("h1").focus({ preventScroll: true });
    }
  }

  // ---------- Building blocks ----------

  function el(tag, attrs, children) {
    const node = document.createElement(tag);
    for (const [key, value] of Object.entries(attrs || {})) {
      if (value == null || value === false) continue;
      if (key === "class") node.className = value;
      else if (key === "text") node.textContent = value;
      else node.setAttribute(key, value === true ? "" : value);
    }
    for (const child of [].concat(children == null ? [] : children)) {
      if (child == null || child === false) continue;
      node.append(child);
    }
    return node;
  }

  const show = (children) => view.replaceChildren(...children.filter(Boolean));
  const heading = (text) => el("h1", { tabindex: "-1", text });
  const mark = (kind, present = true) => el("i", { class: "mark " + kind + (present ? "" : " missing"), "aria-hidden": "true" });
  const plural = (n, word) => n + " " + word + (n === 1 ? "" : "s");

  function describeWeek(week) {
    if (week.overview && week.notes) return "overview and case notes";
    return week.overview ? "overview" : "case notes";
  }

  function breadcrumbs(links, current) {
    return el("nav", { class: "breadcrumbs", "aria-label": "Breadcrumb" },
      el("ol", null, [
        ...links.map(([label, target]) => el("li", null, el("a", { href: target, text: label }))),
        el("li", { "aria-current": "page", text: current }),
      ]));
  }

  function weekStrip(course, current, tab) {
    if (!course.weeks.length) return null;
    return el("ol", { class: "week-strip", "aria-label": "Weeks of " + course.name },
      course.weeks.map((week) => el("li", null,
        el("a", {
          href: href(course, week, tab),
          title: "Week " + week.number + ": " + describeWeek(week),
          "aria-current": week === current ? "page" : null,
        }, [
          el("span", { class: "week-num" }, [el("span", { class: "vh", text: "Week " }), String(week.number)]),
          el("span", { class: "marks" }, [mark("overview", !!week.overview), mark("notes", !!week.notes)]),
        ]))));
  }

  function setSidebar(current, currentWeek) {
    sidebar.hidden = !current;
    layout.classList.toggle("has-sidebar", !!current);
    if (!current) return;
    courseNav.replaceChildren(el("ul", null, courses.map((course) => el("li", null, [
      el("a", {
        class: "tree-course",
        href: href(course),
        "aria-current": course === current && !currentWeek ? "page" : null,
        text: course.name,
      }),
      course === current && course.weeks.length ? el("ul", null, course.weeks.map((week) =>
        el("li", null, el("a", {
          href: href(course, week),
          "aria-current": week === currentWeek ? "page" : null,
          text: "Week " + week.number,
        })))) : null,
    ]))));
  }

  // ---------- Views ----------

  function renderHome() {
    setSidebar(null);
    document.title = "Study Notes | Joris Plettscher";
    show([
      heading("Study notes"),
      el("p", { class: "lede", text: "Claude-generated case notes and weekly overviews of Brain Science courses in order to reduce redundant LLM usage. The overviews explain recurring principles, connections between them and mention important figures from the sources to look at. The notes provide in-detail summaries of all sources." }),
      courses.length ? el("p", { class: "legend" }, [
        el("span", null, [mark("overview"), "Overview"]),
        el("span", null, [mark("notes"), "Case notes"]),
      ]) : null,
      courses.length
        ? el("ul", { class: "course-list" }, courses.map((course) => el("li", null, [
          el("a", { class: "course-link", href: href(course) }, [
            el("span", { class: "course-name", text: course.name }),
            el("span", { class: "course-meta", text: course.weeks.length ? plural(course.weeks.length, "week") : "No weeks yet" }),
          ]),
          weekStrip(course, null),
        ])))
        : el("p", { class: "status", text: "No course notes have been published yet." }),
    ]);
  }

  function renderCourse(course) {
    setSidebar(course, null);
    document.title = course.name + " | Study Notes";

    const docLink = (week, tab, kind, label) =>
      el("a", { class: "doc-link", href: href(course, week, tab) }, [mark(kind), label]);

    show([
      breadcrumbs([["Study notes", "#/"]], course.name),
      heading(course.name),
      el("p", { class: "lede", text: course.weeks.length ? plural(course.weeks.length, "week") + " of notes so far." : "No weeks have been published for this course yet." }),
      course.weeks.length ? el("ul", { class: "week-list" }, course.weeks.map((week) => el("li", null, [
        el("a", { class: "week-title", href: href(course, week), text: "Week " + week.number }),
        el("div", { class: "week-docs" }, [
          week.overview && docLink(week, "overview", "overview", "Overview"),
          week.notes && docLink(week, "notes", "notes", "Case notes"),
          week.notes && week.notes.type === "pdf" && el("a", { class: "doc-link download", href: week.notes.url, download: "", text: "Download PDF" }),
        ]),
      ]))) : null,
      course.other.length ? el("section", { class: "other-files" }, [
        el("h2", { text: "Other files" }),
        el("ul", null, course.other.map((file) =>
          el("li", null, el("a", { href: file.url, target: "_blank", rel: "noopener", text: file.name })))),
      ]) : null,
    ]);
  }

  function renderWeek(course, week, tab) {
    const tabs = [
      { id: "overview", label: "Overview", file: week.overview },
      { id: "notes", label: "Case notes", file: week.notes },
    ];
    const active = tabs.find((t) => t.id === tab && t.file) || tabs.find((t) => t.file);
    const index = course.weeks.indexOf(week);
    const prev = course.weeks[index - 1];
    const next = course.weeks[index + 1];

    setSidebar(course, week);
    document.title = "Week " + week.number + ", " + active.label + " – " + course.name + " | Study Notes";

    show([
      breadcrumbs([["Study notes", "#/"], [course.name, href(course)]], "Week " + week.number),
      el("div", { class: "week-head" }, [heading("Week " + week.number), weekStrip(course, week, active.id)]),
      el("div", { class: "doc-bar" }, [
        el("nav", { class: "doc-tabs", "aria-label": "Documents for week " + week.number }, tabs.map((t) => t.file
          ? el("a", { class: t.id, href: href(course, week, t.id), "aria-current": t === active ? "page" : null }, [mark(t.id), t.label])
          : el("span", { class: "unavailable", text: t.label + " not available" }))),
        el("div", { class: "doc-actions" }, actions(active.file)),
      ]),
      el("div", { class: "viewer" }, viewer(active.file)),
      prev || next ? el("nav", { class: "pager", "aria-label": "Other weeks" }, [
        prev ? el("a", { class: "prev", href: href(course, prev, active.id) }, [el("span", { class: "pager-dir", text: "Previous" }), "Week " + prev.number]) : null,
        next ? el("a", { class: "next", href: href(course, next, active.id) }, [el("span", { class: "pager-dir", text: "Next" }), "Week " + next.number]) : null,
      ]) : null,
    ]);
  }

  function renderMissing(message, course) {
    setSidebar(null);
    document.title = "Not found | Study Notes";
    show([
      heading("Not found"),
      el("p", { class: "lede", text: message }),
      el("p", null, course
        ? el("a", { href: href(course), text: "See all weeks of " + course.name })
        : el("a", { href: "#/", text: "See all courses" })),
    ]);
  }

  // ---------- Document viewers ----------

  function actions(file) {
    if (file.type === "pdf") {
      return [
        el("a", { class: "button primary", href: file.url, download: "", text: "Download PDF" }),
        el("a", { class: "button", href: file.url, target: "_blank", rel: "noopener", text: "Open in new tab" }),
      ];
    }
    return [el("a", { class: "button", href: file.url, target: "_blank", rel: "noopener", text: "Open full page" })];
  }

  function viewer(file) {
    if (file.type === "html") return htmlFrame(file);
    // Desktop browsers have a full PDF viewer built in; phones and tablets mostly don't show PDFs inline.
    const nativePdf = navigator.pdfViewerEnabled && !window.matchMedia("(pointer: coarse)").matches;
    if (nativePdf) return el("iframe", { class: "frame-pdf", src: file.url + "#view=FitH&navpanes=0&pagemode=none", title: file.name });
    const pages = el("div", { class: "pdf-pages" }, el("p", { class: "status", text: "Loading PDF…" }));
    renderPdf(file, pages);
    return pages;
  }

  // Overviews are same-origin pages: grow the frame to the page's height so it reads like part of this page.
  function htmlFrame(file) {
    const frame = el("iframe", { class: "frame-html", src: file.url, title: file.name });
    frame.addEventListener("load", () => {
      let doc;
      try { doc = frame.contentDocument; } catch (e) { return; }
      if (!doc || !doc.documentElement) return;
      doc.documentElement.setAttribute("data-theme", "light");
      let burstStart = 0;
      let burst = 0;
      const fit = () => {
        const height = Math.ceil(doc.documentElement.getBoundingClientRect().height);
        if (Math.abs(height - frame.offsetHeight) < 2) return;
        // Stop if the page's height keeps chasing the frame's (e.g. 100vh layouts).
        const now = Date.now();
        if (now - burstStart > 1000) { burstStart = now; burst = 0; }
        if (++burst > 30) { observer.disconnect(); return; }
        frame.style.height = height + "px";
      };
      const observer = new ResizeObserver(fit);
      observer.observe(doc.documentElement);
      fit();
    });
    return frame;
  }

  let pdfjs = null;
  function loadPdfJs() {
    pdfjs = pdfjs || new Promise((resolve, reject) => {
      const script = el("script", { src: PDFJS + "pdf.min.js" });
      script.onload = () => {
        window.pdfjsLib.GlobalWorkerOptions.workerSrc = PDFJS + "pdf.worker.min.js";
        resolve(window.pdfjsLib);
      };
      script.onerror = () => { pdfjs = null; reject(new Error("PDF.js failed to load")); };
      document.head.append(script);
    });
    return pdfjs;
  }

  // Phone/tablet fallback: draw each page to a canvas as it scrolls near the viewport.
  async function renderPdf(file, container) {
    try {
      const lib = await loadPdfJs();
      const pdf = await lib.getDocument(file.url).promise;
      const first = (await pdf.getPage(1)).getViewport({ scale: 1 });
      const observer = new IntersectionObserver((entries) => {
        for (const entry of entries) {
          if (!entry.isIntersecting) continue;
          observer.unobserve(entry.target);
          drawPage(pdf, entry.target);
        }
      }, { rootMargin: "1000px 0px" });

      container.replaceChildren();
      for (let n = 1; n <= pdf.numPages; n++) {
        const slot = el("div", { class: "pdf-page", "data-page": n, style: "aspect-ratio: " + first.width + " / " + first.height });
        container.append(slot);
        observer.observe(slot);
      }
    } catch (error) {
      console.error(error);
      container.replaceChildren(el("p", { class: "status" }, [
        "This PDF can't be shown here. ",
        el("a", { href: file.url, download: "", text: "Download the PDF" }),
        " to read it.",
      ]));
    }
  }

  async function drawPage(pdf, slot) {
    const number = Number(slot.dataset.page);
    const page = await pdf.getPage(number);
    const base = page.getViewport({ scale: 1 });
    const scale = (slot.clientWidth / base.width) * Math.min(window.devicePixelRatio || 1, 2);
    const viewport = page.getViewport({ scale });
    const canvas = el("canvas", { width: Math.floor(viewport.width), height: Math.floor(viewport.height), role: "img", "aria-label": "Page " + number });
    slot.style.aspectRatio = base.width + " / " + base.height;
    slot.append(canvas);
    await page.render({ canvasContext: canvas.getContext("2d"), viewport }).promise;
  }

  // ---------- Start ----------

  const syncTree = () => { courseTree.open = DESKTOP.matches; };
  DESKTOP.addEventListener("change", syncTree);
  syncTree();

  fetch("manifest.json", { cache: "no-cache" })
    .then((response) => {
      if (!response.ok) throw new Error("HTTP " + response.status);
      return response.json();
    })
    .then((manifest) => {
      courses = buildLibrary(manifest.files || []);
      window.addEventListener("hashchange", render);
      render();
    })
    .catch((error) => {
      // Locally, manifest.json only exists once Jekyll has built the site.
      console.error("Could not load study-notes/manifest.json", error);
      show([
        heading("Study notes"),
        el("p", { class: "status", text: "The list of course notes couldn't be loaded. Reload the page to try again." }),
      ]);
    });
})();
